meta.text:
1.2: split a column's trailing constraint tokens into clause strings, e.g.
`["NOT NULL","DEFAULT 0","PRIMARY KEY"]`. Each CONSTRAINT_START keyword begins a new clause;
tokens before the first constraint keyword are ignored (they belong to the type, read separately).

expr:
return {
          kind: 'raise',
          name: 'RAISE_APPLICATION_ERROR',
          errorCode,
          errorMessage,
          span: { start: startLine, end: this.lineOf() },
        } satisfies RaiseStmt;

return {
        kind: 'call',
        callee: name,
        span: { start: startLine, end: this.lineOf() },
      } satisfies CallStmt;

const { expr, truncated } = clampExpr(
        this.src.slice(exprStart, this.at().off).replace(/\s+/g, ' ').trim(),
      );

return {
        kind: 'assign',
        target: name,
        expr,
        ...(truncated ? { exprTruncated: true } : {}),
        span: { start: startLine, end: this.lineOf() },
      } satisfies AssignStmt;

return {
      kind: 'plain',
      head: name.toUpperCase(),
      span: { start: startLine, end: this.lineOf() },
    };

return {
      kind: 'cursor',
      name,
      cursorQuery,
      ...(cursorTables.length > 0 ? { cursorTables } : {}),
      ...(cursorTruncated ? { exprTruncated: true } : {}),
      span: { start: startLine, end: this.lineOf() },
    };

const dataType = typeParts.reduce((acc, p, i) => {
      if (i === 0) return p;
      if (p.startsWith('(')) return acc + p;
      return `${acc} ${p}`;
    }, '');

return {
      kind: 'variable',
      name,
      dataType,
      ...(constant ? { constant: true } : {}),
      ...(init !== undefined ? { init } : {}),
      ...(exprTruncated ? { exprTruncated: true } : {}),
      span: { start: startLine, end: this.lineOf() },
    };

return {
    kind: 'anonymous',
    name: '',
    span: stmt.span,
    body: { span: stmt.span, statements: [stmt] },
  };

return {
    kind: u.kind === 'function' ? 'function' : 'procedure',
    name: u.name,
    params: u.params,
    returnType: u.returnType,
    span: u.span,
    body: u.body,
    declarations: u.declarations,
  };

const collectFromTables = (): void => {
    for (let i = 0; i < toks.length; i++) {
      const t = tokAt(toks, i);
      if (!t || t.type !== 'word') continue;
      if (t.text === 'from' || t.text === 'join' || t.text === 'using')
        pushFromTable(toks, i, tables);
    }
  };

const out: { tables: string[]; columns: string[]; intoTarget?: string } = {
    tables: dedupe(tables),
    columns: dedupe(columns),
  };

return {
      kind: 'table-ddl',
      schema,
      name,
      columns,
      ...(foreignKeys.length > 0 ? { foreignKeys } : {}),
      span: { start: startLine, end: this.lineOf() },
    };

return {
        kind: 'type-def',
        schema,
        name,
        attributes,
        span: { start: startLine, end: this.lineOf() },
      };

return {
      kind: 'type-def',
      schema,
      name,
      attributes: [],
      collection,
      span: { start: startLine, end: this.lineOf() },
    };

return {
      kind: 'view-ddl',
      schema,
      name,
      columns,
      span: { start: startLine, end: this.lineOf() },
    };

return {
      kind: body ? 'package-body' : 'package',
      name: unitName,
      span: { start: startLine, end: this.lineOf() },
      declarations,
      body: undefined,
    };

return {
        kind,
        name,
        params,
        returnType,
        span: { start: startLine, end: this.lineOf() },
        declarations: [],
        body: { span: { start: startLine, end: this.lineOf() }, statements: [] },
      };

return {
      kind,
      name,
      params,
      returnType,
      span: { start: startLine, end: this.lineOf() },
      declarations,
      body,
    };

return {
      kind: 'anonymous',
      name: '',
      span: { start: startLine, end: this.lineOf() },
      body,
    };

const out: LoopStmt = {
      kind: 'loop',
      loopKind,
      condition,
      body,
      span: { start: startLine, end: this.lineOf() },
    };

branches.push({
        label: 'WHEN',
        condition,
        body,
        span: { start: bStart, end: this.lineOf() },
      });

handlers.push({
        condition,
        body,
        span: { start: hStart, end: this.lineOf() },
      });

const { expr, truncated } = clampExpr(
      this.src.slice(startOff, endOff).replace(/\s+/g, ' ').trim(),
    );

const out: SqlStmt = {
      kind: 'sql',
      sqlKind,
      tables,
      columns,
      expr,
      ...(truncated ? { exprTruncated: true } : {}),
      span: { start: startLine, end: this.at().line },
    };
